import{_ as e,o as n,c as o,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"13 — Quản Trị Trạng Thái Công Việc, Phân Quyền Đa Tầng & Quy Trình Phê Duyệt Hợp Nhất (Task Status & Multi-Role Approval Governance)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/13-task-status-and-approval-governance.md","filePath":"ba/13-task-status-and-approval-governance.md"}'),d={name:"ba/13-task-status-and-approval-governance.md"};function a(i,t,s,r,l,h){return n(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_13-—-quan-tri-trang-thai-cong-viec-phan-quyen-đa-tang-quy-trinh-phe-duyet-hop-nhat-task-status-multi-role-approval-governance" tabindex="-1">13 — Quản Trị Trạng Thái Công Việc, Phân Quyền Đa Tầng &amp; Quy Trình Phê Duyệt Hợp Nhất (Task Status &amp; Multi-Role Approval Governance) <a class="header-anchor" href="#_13-—-quan-tri-trang-thai-cong-viec-phan-quyen-đa-tang-quy-trinh-phe-duyet-hop-nhat-task-status-multi-role-approval-governance" aria-label="Permalink to &quot;13 — Quản Trị Trạng Thái Công Việc, Phân Quyền Đa Tầng &amp; Quy Trình Phê Duyệt Hợp Nhất (Task Status &amp; Multi-Role Approval Governance)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Index</a> · <a href="./10-roles-permissions-matrix.html">← 10 - Roles &amp; Permissions Matrix</a> · <a href="./12-state-machines.html">← 12 - State Machines</a> · <a href="./../feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9 Spec →</a> · <a href="./../feature/modules/04-task-chat-vault/task-subtask-and-inline-workflow/spec.html">Module Subtask &amp; Section Spec →</a> &gt; &gt; Tài liệu này là <strong>Đặc tả Nghiệp vụ Chuẩn (Authoritative BA Specification — v4.0)</strong> giải quyết triệt để mối quan hệ giữa <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>, <strong>4 Vai trò Tham gia Trực tiếp trên Công việc (<code>Coordinator/Assignee</code>, <code>Task Supervisor</code>, <code>Subtask/Section Owner</code>, <code>Subtask Supervisor</code>)</strong>, cơ chế <strong>Tự động Đồng bộ Trạng thái (<code>Section → Subtask → Task → Post</code>)</strong>, và các <strong>Rào chắn Chống Nhảy Cóc Quy trình (<code>Anti-Bypass Invariants</code>)</strong> trên toàn bộ <strong>8 Loại Công việc (<code>TaskType</code>)</strong>.</p><hr><h2 id="_1-boi-canh-cac-van-đe-nghiep-vu-can-khac-phuc-triet-đe" tabindex="-1">1. Bối cảnh &amp; Các Vấn đề Nghiệp vụ Cần Khắc phục Triệt để <a class="header-anchor" href="#_1-boi-canh-cac-van-đe-nghiep-vu-can-khac-phuc-triet-đe" aria-label="Permalink to &quot;1. Bối cảnh &amp; Các Vấn đề Nghiệp vụ Cần Khắc phục Triệt để&quot;">​</a></h2><p>Qua kiểm toán đối chiếu thực tế vận hành (<code>TASK-B2A7</code> và toàn bộ luồng <code>brandhub-business-service</code> ↔ <code>brandhub-web</code>), hệ thống cần đóng kín <strong>10 khoảng trống nghiệp vụ</strong>:</p><ol><li><strong>Chặn lỗ hổng <code>Creator</code> tự chuyển thẳng trạng thái sang <code>Hoàn thành</code> (<code>FINISHED</code>)</strong>: Không cho phép dùng API đổi trạng thái thô (<code>PATCH /tasks/{taskId}/status</code>), kéo thả bảng Kanban hay Thanh thao tác hàng loạt (<code>Bulk Action Bar</code>) để bỏ qua kiểm duyệt <code>TaskSection</code>, <code>Subtask</code> và lượt duyệt của <code>Manager</code> / <code>Client</code>.</li><li><strong>Tự động chuyển trạng thái Task cha (<code>Đang làm</code> → <code>Chờ duyệt</code> → <code>Hoàn thành</code>) khi làm theo từng phần (<code>TaskSection</code>)</strong>: Khắc phục triệt để lỗi duyệt xong 100% các phần (<code>INTERNAL_APPROVED</code> / <code>CLIENT_APPROVED</code>) và toàn bộ <code>Subtask</code> đã hoàn thành nhưng Task cha vẫn bị kẹt ở <code>IN_PROGRESS</code> (<code>Đang làm</code>).</li><li><strong>Đồng bộ đầy đủ quyền của <code>Owner</code> ngang/cao hơn <code>Manager</code></strong>: Khắc phục việc <code>Owner</code> bị chặn nhầm ở <code>SectionPolicy</code> (sửa/duyệt/trả lại/mở lại phần), <code>TaskWorkflowService.start</code> (bắt đầu việc), <code>TaskPlatformPolicy</code> (chọn nền tảng xuất bản), và <code>CampaignSubtaskService</code> (quản lý công việc con độc lập).</li><li><strong>Chuẩn hóa vai trò &quot;Người giám sát&quot; (<code>task.supervisorId</code> &amp; <code>subtask.supervisorOverrideId</code>)</strong>: <ul><li>Đảm bảo <code>task.supervisorId</code> (Người giám sát của Task cha) được kế thừa xuyên suốt xuống mọi <code>Subtask</code> và <code>TaskSection</code> khi công việc con không khai báo <code>supervisorOverrideId</code> riêng.</li><li><strong>Cấm tuyệt đối <code>Creator</code> tự làm Người giám sát của chính mình (<code>Anti-Self-Supervision</code>)</strong>: Khi <code>Creator</code> tạo mới công việc, <code>supervisorId</code> mặc định phải gán về <code>Manager</code>/<code>Owner</code> mặc định của Workspace (<code>defaultManager</code>), không bao giờ gán bằng chính ID của <code>Creator</code> (tránh kích hoạt nhầm <code>skipsAgencyReview</code> bỏ qua bước duyệt nội bộ).</li></ul></li><li><strong>Thống nhất quy tắc duyệt hỗ trợ của <code>Owner</code> &amp; <code>Manager</code></strong>: Dù Task đã chỉ định một <code>Người giám sát</code> cụ thể (có thể là <code>Manager</code> hoặc <code>Creator</code> cấp cao phụ trách QC), mọi <code>Owner</code> và <code>Manager</code> đang hoạt động (khác người trực tiếp thực hiện khi người đó là <code>Creator</code>) vẫn có quyền phê duyệt hỗ trợ/thay thế để luồng sản xuất không bị tắc nghẽn khi Người giám sát vắng mặt.</li><li><strong>Gỡ kẹt trạng thái <code>TODO</code> cho <code>Creator</code> làm Công việc con</strong>: Khi Task cha đang ở <code>TODO</code> (đã đủ Brief &amp; Chiến dịch hợp lệ) mà nhân sự giữ <code>Subtask</code> bắt đầu lưu nội dung phần (<code>Brief</code>, <code>Caption</code>, <code>Media</code>...) hoặc bấm vào không gian làm việc, hệ thống tự động mở phiên <code>TODO → IN_PROGRESS</code> thay vì khóa cứng bắt chờ <code>task.assigneeId</code> bấm nút riêng.</li><li><strong>Thu hồi nút <code>Hoàn tất &amp; Tự duyệt</code> (<code>Self-Approve</code>) khỏi chế độ <code>AGENCY</code></strong>: Nút <code>Self-Approve</code> chỉ dành riêng cho chế độ Cá nhân (<code>workspaceMode = &quot;PERSONAL&quot;</code>). Trong chế độ <code>AGENCY</code> (kể cả khi <code>requiresClientApproval = false</code>), hệ thống tắt hoàn toàn <code>Self-Approve</code> để ngăn việc bấm nhầm làm ép đóng các <code>Subtask</code> và <code>Section</code> chưa hoàn thiện nội dung.</li><li><strong>Mở quyền <code>Mở lại</code> (<code>REOPEN</code>) phần nội dung trên Task <code>FINISHED</code> chưa xuất bản</strong>: Cho phép <code>Owner</code> và <code>Manager</code> bấm <code>REOPEN</code> phần nội dung ngay cả khi Task vừa chuyển <code>FINISHED</code> (miễn bài đăng chưa <code>PUBLISHING</code> / <code>PUBLISHED</code>), tự động đưa Task về <code>IN_PROGRESS</code> và hủy lịch đăng giống cơ chế <code>Client Return</code>.</li><li><strong>Kiểm soát chặt quyền Xuất bản (<code>Publish</code>) &amp; Sửa Đối tác (<code>Partners</code>)</strong>: Chỉ <code>Owner</code>, <code>Manager</code> và nhân sự được phân công vào Task / vai trò xuất bản (<code>POST_PUBLISHING</code>, <code>VIDEO_PUBLISH</code>, <code>EMAIL_SEND</code>, hoặc <code>task.assigneeId</code>) mới được thực thi; chặn <code>Creator</code> không tham gia Task.</li><li><strong>Chuẩn hóa hiển thị Trạng thái (<code>TaskStatusControl</code>), Hàng đợi Duyệt (<code>/task-approvals</code>) &amp; Đồng bộ Tức thì</strong>: <ul><li>Ẩn mũi tên sổ xuống (<code>⌄</code>) trên nhãn trạng thái khi đã <code>FINISHED</code> / <code>CANCELLED</code> hoặc không có thao tác hợp lệ; hiển thị rõ tiến độ phần bên cạnh trạng thái.</li><li>Mở rộng <code>/task-approvals</code> hiển thị đủ <strong>8 loại <code>TaskType</code></strong> (không giới hạn riêng <code>POST</code>).</li><li>Đồng bộ tức thì thay đổi trạng thái từ Panel chi tiết / Editor ra bảng Danh sách, Kanban, Lịch và Gantt.</li></ul></li></ol><hr><h2 id="_2-kien-truc-phan-quyen-2-lop-workspace-role-×-task-participant-role" tabindex="-1">2. Kiến trúc Phân quyền 2 Lớp (Workspace Role × Task Participant Role) <a class="header-anchor" href="#_2-kien-truc-phan-quyen-2-lop-workspace-role-×-task-participant-role" aria-label="Permalink to &quot;2. Kiến trúc Phân quyền 2 Lớp (Workspace Role × Task Participant Role)&quot;">​</a></h2><p>Quyền thực thi trên một Công việc (<code>TaskDocument</code>) luôn được tính bằng giao thoa giữa <strong>Vai trò cấp Workspace</strong> và <strong>Vai trò tham gia trực tiếp trên Công việc</strong>:</p><h3 id="_2-1-đinh-nghia-4-vai-tro-tham-gia-truc-tiep-tren-cong-viec" tabindex="-1">2.1. Định nghĩa 4 Vai trò Tham gia Trực tiếp trên Công việc <a class="header-anchor" href="#_2-1-đinh-nghia-4-vai-tro-tham-gia-truc-tiep-tren-cong-viec" aria-label="Permalink to &quot;2.1. Định nghĩa 4 Vai trò Tham gia Trực tiếp trên Công việc&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vai trò trên Task</th><th style="text-align:left;">Trường Dữ liệu Nguồn</th><th style="text-align:left;">Ai có thể đảm nhận</th><th style="text-align:left;">Trách nhiệm Nghiệp vụ Chính</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Người thực hiện chính / Điều phối viên (<code>Coordinator</code>)</strong></td><td style="text-align:left;"><code>task.assigneeId</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Chịu trách nhiệm tổng thể tiến độ đầu việc; bắt đầu Task (<code>start</code>), soạn/nộp toàn bài (nếu Task không chia Subtask vai trò) hoặc hoàn thiện các phần chưa có chủ sở hữu riêng (<code>unowned sections</code>), quản lý đối tác liên kết (<code>partnerIds</code>).</td></tr><tr><td style="text-align:left;"><strong>2. Người giám sát Task cha (<code>Task Supervisor</code>)</strong></td><td style="text-align:left;"><code>task.supervisorId</code></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, hoặc <code>Creator</code> cấp cao (<strong>khác</strong> <code>task.assigneeId</code> nếu <code>assignee</code> là <code>Creator</code>)</td><td style="text-align:left;">Chịu trách nhiệm kiểm duyệt chất lượng nội bộ cho toàn bộ Task và mặc định làm người duyệt nội bộ cho các <code>Subtask</code> / <code>TaskSection</code> chưa gán người giám sát riêng.</td></tr><tr><td style="text-align:left;"><strong>3. Người thực hiện Công việc con / Chủ phần (<code>Section Writer / Owner</code>)</strong></td><td style="text-align:left;"><code>subtask.assigneeId</code> (gắn <code>subtask.subtaskRole</code>)</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Trực tiếp biên soạn, lưu nháp, khôi phục lịch sử phiên bản và bấm <code>Nộp duyệt phần</code> (<code>SUBMIT</code>) cho các <code>TaskSection</code> thuộc <code>subtaskRole</code> mình đảm nhận.</td></tr><tr><td style="text-align:left;"><strong>4. Người giám sát Công việc con (<code>Subtask Supervisor</code>)</strong></td><td style="text-align:left;"><code>subtask.supervisorOverrideId</code> (fallback về <code>task.supervisorId</code>, rồi <code>defaultManager</code>)</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, hoặc <code>Creator</code> cấp cao (<strong>khác</strong> <code>subtask.assigneeId</code>)</td><td style="text-align:left;">Kiểm duyệt nội bộ (<code>APPROVE</code> / <code>RETURN</code>) riêng cho các <code>TaskSection</code> thuộc <code>Subtask</code> được phân công giám sát.</td></tr></tbody></table><h3 id="_2-2-quy-tac-bat-bien-chong-tu-giam-sat-br-34a-—-anti-self-supervision" tabindex="-1">2.2. Quy tắc Bất biến Chống Tự Giám Sát (<code>BR-34a — Anti-Self-Supervision</code>) <a class="header-anchor" href="#_2-2-quy-tac-bat-bien-chong-tu-giam-sat-br-34a-—-anti-self-supervision" aria-label="Permalink to &quot;2.2. Quy tắc Bất biến Chống Tự Giám Sát (`BR-34a — Anti-Self-Supervision`)&quot;">​</a></h3><ol><li><strong>Cấm <code>Creator</code> tự giám sát chính mình</strong>: <ul><li>Nếu <code>task.assigneeId</code> là thành viên mang vai trò <code>Creator</code>, trường <code>task.supervisorId</code> <strong>không bao giờ được trùng với <code>task.assigneeId</code></strong>.</li><li>Khi <code>Creator</code> khởi tạo Task mới (<code>createTask</code> hoặc <code>createStandaloneTask</code>) mà không chọn <code>supervisorId</code> (hoặc truyền chính ID của mình), Backend tự động gán <code>task.supervisorId = defaultManager(workspaceId)</code> (lấy <code>Manager</code> hoặc <code>Owner</code> đang hoạt động của Workspace).</li><li>Khi cập nhật <code>PATCH /tasks/{taskId}/field</code> với <code>field = &quot;supervisorId&quot;</code> (hoặc cập nhật <code>subtask.supervisorOverrideId</code>), nếu người nhận việc (<code>assigneeId</code>) là <code>Creator</code> và <code>supervisorId == assigneeId</code> → từ chối với mã lỗi <code>400 VALIDATION_ERROR</code> (<code>INVALID_TASK_SUPERVISOR</code>).</li></ul></li><li><strong>Điều kiện duy nhất được bỏ qua bước duyệt nội bộ (<code>skipsAgencyReview</code>)</strong>: <ul><li>Chỉ khi người thực hiện chính (<code>task.assigneeId</code>) có vai trò <strong><code>Owner</code> hoặc <code>Manager</code></strong> VÀ <code>task.supervisorId</code> trùng với <code>task.assigneeId</code> (hoặc đang ở chế độ <code>PERSONAL</code>), hệ thống mới cho phép bỏ qua bước chờ <code>MANAGER</code> duyệt để chuyển thẳng sang bước <code>CLIENT</code> (nếu <code>requiresClientApproval = true</code>) hoặc <code>FINISHED</code> (nếu <code>requiresClientApproval = false</code>).</li></ul></li></ol><h3 id="_2-3-ma-tran-quyen-chi-tiet-theo-tung-vai-tro-va-hanh-đong-che-đo-agency" tabindex="-1">2.3. Ma trận Quyền Chi tiết theo Từng Vai trò và Hành động (Chế độ <code>AGENCY</code>) <a class="header-anchor" href="#_2-3-ma-tran-quyen-chi-tiet-theo-tung-vai-tro-va-hanh-đong-che-đo-agency" aria-label="Permalink to &quot;2.3. Ma trận Quyền Chi tiết theo Từng Vai trò và Hành động (Chế độ `AGENCY`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Hành động Nghiệp vụ</th><th style="text-align:center;"><code>Owner</code></th><th style="text-align:center;"><code>Manager</code></th><th style="text-align:center;"><code>Task Supervisor</code> (<code>Creator</code> giám sát, <code>≠ assignee</code>)</th><th style="text-align:center;"><code>Coordinator</code> (<code>Creator</code> là <code>task.assigneeId</code>)</th><th style="text-align:center;"><code>Section Owner</code> (<code>Creator</code> là <code>subtask.assigneeId</code>)</th><th style="text-align:center;"><code>Creator</code> khác (ngoài Task)</th><th style="text-align:center;"><code>Client</code></th></tr></thead><tbody><tr><td style="text-align:left;">Xem Task &amp; các phần <code>OUTPUT</code></td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔ (Chỉ đọc)</td><td style="text-align:center;">✔ (Chỉ phần <code>OUTPUT</code> đã duyệt nội bộ)</td></tr><tr><td style="text-align:left;">Xem các phần nội bộ <code>INTERNAL</code> &amp; Lịch sử phiên bản (<code>Versions</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖ (Ẩn tuyệt đối)</strong></td></tr><tr><td style="text-align:left;">Sửa Brief, Hạn chót, Giao người thực hiện, Gán Người giám sát (<code>TODO</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Chọn / Đổi Nền tảng xuất bản (<code>targetPlatforms</code>: FB, IG, TikTok, Threads)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Thêm / Sửa / Sắp xếp Công việc con (<code>Subtasks</code> — cả Campaign &amp; Standalone)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Gắn / Gỡ Đối tác (<code>partnerIds</code>) trên Task đang mở</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Bấm <code>Bắt đầu làm</code> (<code>TODO → IN_PROGRESS</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔ <em>(Tự mở khi bắt đầu lưu phần)</em></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Sửa &amp; Lưu nháp phần nội dung (<code>Section</code> / <code>Post</code>) khi Task đang mở</td><td style="text-align:center;">✔ (Mọi phần)</td><td style="text-align:center;">✔ (Mọi phần)</td><td style="text-align:center;">✖ <em>(Trừ phần mình sở hữu)</em></td><td style="text-align:center;">✔ (Mọi phần đang mở)</td><td style="text-align:center;">✔ (Phần mình sở hữu ở <code>DRAFT</code>/<code>RETURNED</code>)</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Bấm <code>Nộp duyệt phần</code> (<code>Section SUBMIT</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔ (Phần mình sở hữu)</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;"><strong>Duyệt nội bộ / Trả lại phần (<code>Section APPROVE / RETURN</code>)</strong></td><td style="text-align:center;"><strong>✔</strong></td><td style="text-align:center;"><strong>✔</strong></td><td style="text-align:center;"><strong>✔</strong> <em>(Phần mình giám sát, không sở hữu)</em></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;"><strong>Mở lại phần đã duyệt (<code>Section REOPEN</code> — kể cả Task <code>FINISHED</code> chưa đăng)</strong></td><td style="text-align:center;"><strong>✔</strong></td><td style="text-align:center;"><strong>✔</strong></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖ <em>(Client dùng <code>RETURN</code>)</em></td></tr><tr><td style="text-align:left;"><strong>Duyệt / Trả lại cấp Khách hàng (<code>CLIENT_APPROVE / CLIENT_RETURN</code>)</strong></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;"><strong>✔</strong> <em>(Khi <code>requiresClientApproval = true</code>)</em></td></tr><tr><td style="text-align:left;">Gửi duyệt / Thu hồi Task đơn không chia Subtask (<code>Task SUBMIT / WITHDRAW</code>)</td><td style="text-align:center;">✔ <em>(Nếu là <code>assignee</code>)</em></td><td style="text-align:center;">✔ <em>(Nếu là <code>assignee</code>)</em></td><td style="text-align:center;">✖</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Duyệt / Từ chối Task đơn ở bước <code>MANAGER</code> (<code>Task APPROVE / REJECT</code>)</td><td style="text-align:center;"><strong>✔</strong> <em>(Khác <code>Creator</code> nộp)</em></td><td style="text-align:center;"><strong>✔</strong> <em>(Khác <code>Creator</code> nộp)</em></td><td style="text-align:center;"><strong>✔</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Duyệt / Từ chối Task đơn ở bước <code>CLIENT</code> (<code>Task APPROVE / REJECT</code>)</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;"><strong>✔</strong></td></tr><tr><td style="text-align:left;">Dùng nút tắt <code>Hoàn tất &amp; Tự duyệt</code> (<code>Self-Approve</code>)</td><td style="text-align:center;"><strong>✖</strong> <em>(Chỉ mở ở <code>PERSONAL</code>)</em></td><td style="text-align:center;"><strong>✖</strong> <em>(Chỉ mở ở <code>PERSONAL</code>)</em></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Đổi trạng thái sang <code>Hủy</code> (<code>CANCELLED</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Đổi thẳng trạng thái sang <code>FINISHED</code> / <code>IN_REVIEW</code> qua Kanban / Bulk / <code>PATCH /status</code></td><td style="text-align:center;"><strong>✖ (Bị chặn)</strong></td><td style="text-align:center;"><strong>✖ (Bị chặn)</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;"><strong>✖</strong></td></tr><tr><td style="text-align:left;">Lên lịch lại (<code>Reschedule</code>) sau khi duyệt</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td><td style="text-align:center;">✔ <em>(Vai trò <code>*_PUBLISH</code>)</em></td><td style="text-align:center;">✖</td><td style="text-align:center;">✖</td></tr><tr><td style="text-align:left;">Bấm <code>Đăng ngay</code> (<code>Publish Post</code>) khi Task đã <code>FINISHED</code> (<code>APPROVED</code>)</td><td style="text-align:center;">✔</td><td style="text-align:center;">✔</td><td style="text-align:center;">✖</td><td style="text-align:center;">✔ <em>(Task đơn không chia vai trò)</em></td><td style="text-align:center;">✔ <em>(Vai trò <code>POST_PUBLISHING</code> / <code>VIDEO_PUBLISH</code>)</em></td><td style="text-align:center;"><strong>✖</strong></td><td style="text-align:center;">✖</td></tr></tbody></table><p>&gt; <strong>Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>: Chủ không gian (<code>Owner</code> / <code>Manager</code>) nắm toàn quyền biên soạn, chọn kênh, xuất file và được mở nút <strong><code>Hoàn tất &amp; Tự duyệt</code> (<code>Self-Approve</code> 1 chạm)</strong> để chốt nhanh công việc cá nhân sang <code>FINISHED</code> (vẫn kiểm tra bài đăng <code>POST</code> / <code>SHORT_VIDEO</code> phải có nội dung trước khi xuất bản).</p><hr><h2 id="_3-quy-trinh-đong-bo-trang-thai-tu-đong-section-→-subtask-→-task-→-post" tabindex="-1">3. Quy Trình Đồng Bộ Trạng Thái Tự Động (<code>Section → Subtask → Task → Post</code>) <a class="header-anchor" href="#_3-quy-trinh-đong-bo-trang-thai-tu-đong-section-→-subtask-→-task-→-post" aria-label="Permalink to &quot;3. Quy Trình Đồng Bộ Trạng Thái Tự Động (`Section → Subtask → Task → Post`)&quot;">​</a></h2><p>Hệ thống vận hành theo <strong>2 mô hình công việc</strong> nhưng hội tụ về <strong>cùng một tập 5 trạng thái chuẩn của Task cha</strong> (<code>TODO</code>, <code>IN_PROGRESS</code>, <code>IN_REVIEW</code>, <code>FINISHED</code>, <code>CANCELLED</code>):</p><h3 id="_3-1-mo-hinh-1-—-cong-viec-co-phan-ra-phan-vai-tro-roletask-true-ap-dung-cho-ca-8-tasktype" tabindex="-1">3.1. Mô hình 1 — Công việc Có Phân rã Phần &amp; Vai trò (<code>roleTask = true</code>, áp dụng cho cả 8 <code>TaskType</code>) <a class="header-anchor" href="#_3-1-mo-hinh-1-—-cong-viec-co-phan-ra-phan-vai-tro-roletask-true-ap-dung-cho-ca-8-tasktype" aria-label="Permalink to &quot;3.1. Mô hình 1 — Công việc Có Phân rã Phần &amp; Vai trò (`roleTask = true`, áp dụng cho cả 8 `TaskType`)&quot;">​</a></h3><p>Khi Task có ít nhất một <code>Subtask</code> gắn <code>subtaskRole</code> đang hoạt động (<code>status != &quot;CANCELLED&quot;</code>):</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T0[&quot;Task: TODO (Cần làm)&quot;] --&gt;|&quot;Coordinator bấm Bắt đầu HOẶC Chủ phần lưu nháp đầu tiên&quot;| T1[&quot;Task: IN_PROGRESS (Đang làm)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T1 --&gt; S1[&quot;Creator nộp từng Section (DRAFT/RETURNED → SUBMITTED)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S1 --&gt; S2{&quot;Owner / Manager / Supervisor duyệt nội bộ&quot;}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S2 --&gt;|&quot;Trả lại kèm lý do (RETURN)&quot;| S1</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S2 --&gt;|&quot;Duyệt nội bộ (INTERNAL_APPROVED)&quot;| CHECK_ALL{&quot;100% Section bắt buộc đã đạt tối thiểu INTERNAL_APPROVED &amp; không còn Free Subtask mở?&quot;}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CHECK_ALL --&gt;|&quot;Chưa đủ (ví dụ 3/5 phần)&quot;| T1</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CHECK_ALL --&gt;|&quot;Đã đủ 100% phần nội bộ&quot;| REQ_CLIENT{&quot;Task có requiresClientApproval = true?&quot;}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    REQ_CLIENT --&gt;|&quot;Không (Chỉ duyệt nội bộ)&quot;| DONE[&quot;TỰ ĐỘNG CHỐT: Task → FINISHED (Hoàn thành)&lt;br/&gt;Subtasks → FINISHED&lt;br/&gt;Post → SCHEDULED / APPROVED&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    REQ_CLIENT --&gt;|&quot;Có (Cần Client duyệt phần OUTPUT)&quot;| T2[&quot;TỰ ĐỘNG CHUYỂN: Task → IN_REVIEW (reviewStep = CLIENT)&lt;br/&gt;Post → PENDING_APPROVAL&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T2 --&gt; C_DECIDE{&quot;Client duyệt từng phần OUTPUT&quot;}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C_DECIDE --&gt;|&quot;Client trả lại 1 phần bất kỳ (CLIENT_RETURN + lý do)&quot;| REOPEN_FLOW[&quot;Phần đó → RETURNED · Subtask đó → IN_PROGRESS&lt;br/&gt;Task tự quay về IN_PROGRESS · Hủy lịch đăng (nếu có)&lt;br/&gt;Các phần khác giữ nguyên trạng thái đã duyệt&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C_DECIDE --&gt;|&quot;Client duyệt phần OUTPUT cuối cùng (100% finalState)&quot;| DONE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DONE --&gt;|&quot;Client RETURN hoặc Owner/Manager REOPEN 1 phần (khi Post chưa đăng)&quot;| REOPEN_FLOW</span></span></code></pre></div><p><strong>Các quy tắc tính toán chính xác khi tự động chốt (<code>Auto-Settle Rules</code>)</strong>:</p><ol><li><strong>Xác định các phần không có chủ sở hữu riêng (<code>Unowned Sections</code>)</strong>: <ul><li>Nếu một <code>TaskSection</code> không có <code>Subtask</code> nào đang hoạt động giữ vai trò sở hữu (ví dụ <code>Manager</code> xóa bớt 1 <code>Subtask</code> phụ): <ul><li>Với phần gắn nội dung <code>PostDocument</code> (<code>POST.CAPTION</code>, <code>VIDEO.CAPTION</code>): chỉ được coi là hợp lệ để tự động đóng khi nội dung bắt buộc (như <code>caption</code>) không rỗng.</li><li>Khi tất cả các phần có chủ sở hữu đã được duyệt nội bộ (<code>INTERNAL_APPROVED</code> / <code>CLIENT_APPROVED</code>) và phần không chủ sở hữu đã thỏa điều kiện nội dung, hệ thống tự động đóng dấu <code>INTERNAL_APPROVED</code> cho phần không chủ sở hữu (và bật <code>clientPendingSince</code> nếu là phần <code>OUTPUT</code> cần <code>Client</code> duyệt).</li></ul></li></ul></li><li><strong>Trường hợp <code>Client</code> duyệt song song sớm</strong>: <ul><li>Ngay khi một phần <code>OUTPUT</code> đạt <code>INTERNAL_APPROVED</code> trên Task có <code>requiresClientApproval = true</code>, phần đó hiển thị ngay cho <code>Client</code> duyệt mà không bắt chờ các phần khác xong hết.</li><li>Nếu <code>Client</code> đã duyệt xong các phần <code>OUTPUT</code> (<code>CLIENT_APPROVED</code>) trước, và sau đó <code>Manager</code> bấm duyệt nốt phần <code>INTERNAL</code> cuối cùng (như <code>POST.BRIEF</code> hoặc <code>VIDEO.SHOOT</code>) → tại đúng thời điểm phần cuối cùng đạt <code>finalState = true</code>, hệ thống <strong>tự động chốt Task cha sang <code>FINISHED</code> ngay lập tức</strong>!</li></ul></li></ol><h3 id="_3-2-mo-hinh-2-—-cong-viec-đon-khong-chia-subtask-vai-tro-roletask-false" tabindex="-1">3.2. Mô hình 2 — Công việc Đơn Không Chia Subtask Vai trò (<code>roleTask = false</code>) <a class="header-anchor" href="#_3-2-mo-hinh-2-—-cong-viec-đon-khong-chia-subtask-vai-tro-roletask-false" aria-label="Permalink to &quot;3.2. Mô hình 2 — Công việc Đơn Không Chia Subtask Vai trò (`roleTask = false`)&quot;">​</a></h3><ol><li><code>TODO</code> → <code>Coordinator</code> (<code>task.assigneeId</code>) bấm <code>Bắt đầu làm</code> → <code>IN_PROGRESS</code>.</li><li><code>IN_PROGRESS</code> → <code>Coordinator</code> hoàn thiện nội dung (với <code>POST</code>/<code>SHORT_VIDEO</code> bắt buộc <code>caption</code> không trống) và bấm <code>Gửi duyệt</code> (<code>POST /submit</code>): <ul><li>Nếu <code>skipsAgencyReview == true</code> (tức <code>Owner</code> hoặc <code>Manager</code> tự thực hiện và tự giám sát): <ul><li>Không cần <code>Client</code> → chuyển thẳng <code>FINISHED</code> (<code>Post</code> → <code>SCHEDULED</code> / <code>APPROVED</code>).</li><li>Cần <code>Client</code> → chuyển <code>IN_REVIEW</code> (<code>reviewStep = &quot;CLIENT&quot;</code>).</li></ul></li><li>Nếu <code>skipsAgencyReview == false</code> (do <code>Creator</code> thực hiện hoặc có Người giám sát khác): <ul><li>Chuyển <code>IN_REVIEW</code> (<code>reviewStep = &quot;MANAGER&quot;</code>).</li></ul></li></ul></li><li><code>IN_REVIEW (MANAGER)</code> → <code>Owner</code> / <code>Manager</code> / <code>Task Supervisor</code> quyết định: <ul><li><code>Approve</code>: Nếu không cần <code>Client</code> → <code>FINISHED</code>; nếu cần <code>Client</code> → <code>IN_REVIEW (CLIENT)</code>.</li><li><code>Reject</code> (bắt buộc nhập lý do) → quay về <code>IN_PROGRESS</code> (<code>reviewStep = null</code>), lần gửi lại kế tiếp tăng <code>approvalRound + 1</code>.</li><li>Trước khi có quyết định ở bước <code>MANAGER</code>, <code>Coordinator</code> được quyền <code>Thu hồi</code> (<code>Withdraw</code>) về <code>IN_PROGRESS</code>.</li></ul></li><li><code>IN_REVIEW (CLIENT)</code> → Một <code>Client</code> đang hoạt động bất kỳ trong Workspace quyết định: <ul><li><code>Approve</code> → <code>FINISHED</code> (<code>Post</code> → <code>SCHEDULED</code> / <code>APPROVED</code>).</li><li><code>Reject</code> (bắt buộc nhập lý do) → quay về <code>IN_PROGRESS</code>, giữ nguyên toàn bộ lịch sử <code>task_approvals</code> của vòng cũ.</li></ul></li></ol><hr><h2 id="_4-rao-chan-chong-nhay-coc-patch-status-kanban-bulk-action" tabindex="-1">4. Rào chắn Chống Nhảy Cóc (<code>PATCH /status</code>, Kanban &amp; Bulk Action) <a class="header-anchor" href="#_4-rao-chan-chong-nhay-coc-patch-status-kanban-bulk-action" aria-label="Permalink to &quot;4. Rào chắn Chống Nhảy Cóc (`PATCH /status`, Kanban &amp; Bulk Action)&quot;">​</a></h2><p>Để bịt kín mọi đường vòng (backdoor) trên giao diện và API:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Thao tác đầu vào trên <code>PATCH /tasks/{taskId}/status</code></th><th style="text-align:left;">Quy tắc Kiểm tra Bắt buộc tại Backend (<code>TaskServiceImpl.updateStatus</code>)</th><th style="text-align:left;">Hành vi tương ứng trên Kanban &amp; Bulk Action</th></tr></thead><tbody><tr><td style="text-align:left;">Chuyển sang <strong><code>FINISHED</code></strong></td><td style="text-align:left;"><strong>TỪ CHỐI (<code>409 TASK_WORKFLOW_REQUIRED</code>)</strong> đối với mọi Task thuộc quy trình phê duyệt (<code>TaskApprovalPolicy.supported</code>), bất kể người gọi là <code>Creator</code>, <code>Manager</code> hay <code>Owner</code>. Trạng thái <code>FINISHED</code> chỉ được thiết lập thông qua <code>TaskApprovalService</code> / <code>SectionService</code> khi đã qua phê duyệt hợp lệ!</td><td style="text-align:left;">Không cho thả thẻ trực tiếp vào cột <code>Hoàn thành</code> (hiện thông báo hướng dẫn mở Task/Editor để hoàn tất phê duyệt); ẩn lựa chọn <code>Hoàn thành</code> trong menu Đổi trạng thái hàng loạt (<code>TaskBulkActionBar</code>).</td></tr><tr><td style="text-align:left;">Chuyển sang <strong><code>IN_REVIEW</code></strong></td><td style="text-align:left;"><strong>TỪ CHỐI (<code>409 TASK_WORKFLOW_REQUIRED</code>)</strong>. Muốn gửi duyệt phải gọi <code>POST /tasks/{id}/submit</code> hoặc <code>POST /sections/{key}/submit</code> để hệ thống kiểm tra <code>caption</code>, <code>subtasks</code>, <code>revision</code> và kích hoạt thông báo người duyệt.</td><td style="text-align:left;">Cột <code>Chờ duyệt</code> trên Kanban không nhận kéo-thả thủ công từ cột nháp; ẩn lựa chọn <code>Chờ duyệt</code> trong <code>TaskBulkActionBar</code>.</td></tr><tr><td style="text-align:left;">Chuyển sang <strong><code>CANCELLED</code></strong></td><td style="text-align:left;">Chỉ cho phép <strong><code>Owner</code> hoặc <code>Manager</code></strong> (chặn <code>Creator</code> với <code>403 FORBIDDEN</code>). Khi hủy phải ghi nhận <code>Cancellation</code>, xóa <code>reviewStep</code>, và hủy lịch đăng bài nếu có.</td><td style="text-align:left;"><code>Creator</code> không thể kéo thẻ sang <code>Đã hủy</code> và không thấy tùy chọn <code>Đã hủy</code> trong Bulk Action.</td></tr><tr><td style="text-align:left;">Chuyển <strong><code>TODO → IN_PROGRESS</code></strong></td><td style="text-align:left;">Cho phép <code>Owner</code>, <code>Manager</code>, hoặc <code>Creator</code> được phân công (<code>task.assigneeId</code>) khi Task đã có đủ Brief/Hạn chót và Chiến dịch cho phép bắt đầu (tương đương <code>start</code>). Từ chối nếu Task đang <code>FINISHED</code> hoặc <code>CANCELLED</code> (<code>409 TASK_WORKFLOW_LOCKED</code>).</td><td style="text-align:left;">Kéo thẻ từ <code>Cần làm</code> sang <code>Đang làm</code> hoạt động hợp lệ cho người được giao.</td></tr><tr><td style="text-align:left;">Chuyển <strong><code>IN_PROGRESS → TODO</code></strong></td><td style="text-align:left;">Chỉ cho phép <code>Owner</code> / <code>Manager</code> khi Task <strong>chưa từng bắt đầu thực tế</strong> (<code>firstStartedAt == null</code>) và chưa có phần nội dung nào được nộp (<code>SUBMITTED</code> / <code>APPROVED</code>).</td><td style="text-align:left;">Tránh làm hỏng lịch sử <code>firstStartedAt</code> của các Task đang sản xuất.</td></tr></tbody></table><hr><h2 id="_5-quy-chuan-hien-thi-ui-ux-trang-thai-đong-bo-du-lieu" tabindex="-1">5. Quy chuẩn Hiển thị UI/UX Trạng thái &amp; Đồng bộ Dữ liệu <a class="header-anchor" href="#_5-quy-chuan-hien-thi-ui-ux-trang-thai-đong-bo-du-lieu" aria-label="Permalink to &quot;5. Quy chuẩn Hiển thị UI/UX Trạng thái &amp; Đồng bộ Dữ liệu&quot;">​</a></h2><ol><li><strong>Thanh Trạng thái ở Header Task Detail (<code>TaskStatusControl</code>)</strong>: <ul><li><strong>Trạng thái tĩnh khi không có hành động chuyển đổi</strong>: Khi Task đã <code>FINISHED</code> (<code>Hoàn thành</code>), <code>CANCELLED</code> (<code>Đã hủy</code>), hoặc vai trò hiện tại không có hành động hợp lệ nào trong menu → hiển thị <strong>Badge trạng thái tĩnh</strong> (không render <code>DropdownMenuTrigger</code>, không hiện icon mũi tên <code>⌄</code>, không mở menu trống <em>&quot;Không có thao tác chuyển trạng thái&quot;</em>).</li><li><strong>Hiển thị rõ Ngữ cảnh &amp; Tiến độ Duyệt ngay trên Header</strong>: <ul><li>Khi <code>IN_PROGRESS</code> trên Task chia phần: hiển thị kèm tiến độ phần đã duyệt (ví dụ: <code>3/5 phần đã duyệt</code> hoặc <code>Chờ duyệt nội bộ 1 phần</code>).</li><li>Khi <code>IN_REVIEW</code>: hiển thị rõ bước đang chờ (<code>Chờ Quản lý duyệt</code> hoặc <code>Chờ Khách hàng duyệt</code>).</li><li>Khi <code>FINISHED</code>: hiển thị rõ kết quả đầu ra (<code>Đã duyệt · Lên lịch đăng</code> hoặc <code>Đã hoàn tất phê duyệt</code>).</li></ul></li></ul></li><li><strong>Trang Hàng đợi Phê duyệt (<code>/workspaces/:id/task-approvals</code>)</strong>: <ul><li>Tải đầy đủ tất cả <strong>8 loại <code>TaskType</code></strong> (<code>POST</code>, <code>SHORT_VIDEO</code>, <code>SURVEY</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code>), có bộ lọc theo <code>TaskType</code> và <code>Trạng thái</code> (<code>IN_REVIEW</code>, <code>IN_PROGRESS</code> có phần đang <code>SUBMITTED</code>, <code>FINISHED</code>).</li></ul></li><li><strong>Đồng bộ Tức thì với Danh sách Công việc Bên ngoài (<code>List</code>, <code>Kanban</code>, <code>Calendar</code>, <code>Gantt</code>)</strong>: <ul><li>Mọi thao tác nộp phần, duyệt phần, trả lại phần, mở lại phần, gửi duyệt Task, duyệt/từ chối Task trên <code>TaskDetailPanel</code> hoặc <code>Editor</code> đều phát tín hiệu cập nhật (<code>onUpdated</code> + invalidate React Query keys <code>[&quot;tasks&quot;]</code>, <code>[&quot;task-workflow&quot;]</code>, <code>[&quot;task-review&quot;]</code>, <code>[&quot;task-sections&quot;]</code>, <code>[&quot;campaign-subtasks&quot;]</code>) để dòng/thẻ bên ngoài đổi màu và nhãn trạng thái ngay lập tức.</li></ul></li></ol>',33)])])}const p=e(d,[["render",a]]);export{u as __pageData,p as default};
